// @ts-check
// Safe file names and object keys. The client's file name is kept only as
// metadata; the S3 key is generated by the server, so a name like
// "../../etc/passwd" or "invoice.pdf\u202Eexe" can never choose where a file lands.
import crypto from 'node:crypto';

/**
 * Clean a client-supplied file name for display and Content-Disposition.
 * @param {string} name
 */
export function sanitizeFilename(name) {
  let n = String(name || '').normalize('NFKC');
  n = n.split(/[\\/]/).pop() || ''; // drop any path
  n = n
    .replace(/[\u0000-\u001f\u007f-\u009f]/g, '') // control chars
    .replace(/[\u200b-\u200f\u202a-\u202e\u2066-\u2069\ufeff]/g, '') // bidi/zero-width tricks
    .replace(/[<>:"|?*%]/g, '_')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/^\.+/, ''); // no hidden files / ".."
  if (n.length > 150) {
    const ext = n.match(/\.[A-Za-z0-9]{1,8}$/)?.[0] || '';
    n = n.slice(0, 150 - ext.length) + ext;
  }
  return n || 'file';
}

/** Tenant / client ids: lowercase slug. */
export function sanitizeTenant(tenant) {
  const t = String(tenant || 'default').toLowerCase().replace(/[^a-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 64);
  return t || 'default';
}

export function newId(prefix = 'f') {
  return `${prefix}_${crypto.randomBytes(12).toString('base64url')}`;
}

/**
 * Object key: <prefix>/<tenant>/<yyyy>/<mm>/<fileId>.<ext>
 * @param {{ prefix?: string, tenant: string, fileId: string, ext: string, date?: Date }} p
 */
export function buildObjectKey({ prefix = '', tenant, fileId, ext, date = new Date() }) {
  const yyyy = String(date.getUTCFullYear());
  const mm = String(date.getUTCMonth() + 1).padStart(2, '0');
  const safeExt = String(ext || 'bin').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 8) || 'bin';
  return [prefix, sanitizeTenant(tenant), yyyy, mm, `${fileId}.${safeExt}`].filter(Boolean).join('/');
}

/** RFC 6266 Content-Disposition with an ASCII fallback and UTF-8 name. */
export function contentDisposition(filename, type = 'attachment') {
  const clean = sanitizeFilename(filename);
  const ascii = clean.replace(/[^\x20-\x7e]/g, '_').replace(/["\\]/g, '_');
  return `${type}; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(clean)}`;
}
